"""Preserve error-statistic scope independently of effect size and assay family."""
import csv,json
from pathlib import Path
P=Path(__file__).resolve().parent
records=[
dict(doi='10.3390/foods10081807',locator='Table 5 caption; ORAC Results; Methods 2.5.4',statistic='SD',reported_n='3',replication='Author-declared independent experiments',definition_scope='Explicitly ORAC values in Table 5, not IC50 confidence intervals',variance_candidate_rule='SD squared / 3; conditional author independence',variance_approval='NOT_APPROVED_SHARED_CALIBRATION_COVARIANCE_UNRESOLVED',remaining='Figure S5 calibration curves, within-run technical structure and slope uncertainty not inspected',inference_boundary='Article reports no statistically significant ORAC difference among the three phytochemicals; numerical order is descriptive'),
dict(doi='10.1039/d1ra08918h',locator='Table 1 SD column; Methods 2.2; reference 5',statistic='SD',reported_n='3 measurements',replication='Independent batches not established',definition_scope='Explicit compound-level SD; do not borrow interlaboratory precision',variance_candidate_rule='None until experimental-unit structure is established',variance_approval='NOT_APPROVED',remaining='Actual Watanabe A/B variant and supporting implementation records unresolved; publisher HTML access 403 in this check',inference_boundary='Do not interpret three measurements as three independent experiments'),
dict(doi='10.3390/antiox11091784',locator='Table 2; Methods 2.2.2 and 2.3',statistic='UNRESOLVED_PLUS_MINUS',reported_n='3 replicates',replication='Independent batches not established',definition_scope='Three replicates identifies count, not SD versus SE',variance_candidate_rule='None',variance_approval='NOT_APPROVED',remaining='Inherited protocol, explicit plus/minus definition and covariance across doses unresolved',inference_boundary='Two concentrations from one paper are not independent studies; rounded zero error is not zero variance'),
dict(doi='10.3390/ijms150916351',locator='Table 2; Methods 3.2.3',statistic='UNRESOLVED_PLUS_MINUS',reported_n='4 replicates',replication='Independent batches not established',definition_scope='ORAC-specific replicate statement; ABTS counts are not borrowed',variance_candidate_rule='None',variance_approval='NOT_APPROVED',remaining='Experimental error definition and calibration uncertainty unresolved',inference_boundary='Do not calculate SD squared / 4 from an undefined plus/minus statistic'),
dict(doi='10.3390/antiox12020505',locator='Table 3; ORAC Methods; data comparison',statistic='UNRESOLVED_PLUS_MINUS',reported_n='Triplicate solutions on two days',replication='Effective independent n for slope ratio unresolved',definition_scope='Endpoint-ratio uncertainty cannot be inferred from well count',variance_candidate_rule='None',variance_approval='NOT_APPROVED',remaining='Error propagation and calibration covariance unresolved',inference_boundary='Neither n=6 nor n=30 is inferred')]
for r in records:r.update(human_review_status='NOT_REVIEWED',change_applied='NO')
