with (P/'results/Bridge_Error_Definition_Audit.csv').open('w',encoding='utf-8-sig',newline='') as f:
    w=csv.DictWriter(f,fieldnames=list(records[0]));w.writeheader();w.writerows(records)
print('QC PASS: two explicit SD sources, three unresolved error definitions; no approved weights.')
